-- Tests grant locally only AFTER proving candidate ACL is closed.
SELECT pg_temp.assert_true('claim closed',NOT has_function_privilege('authenticated','public.b2b_claim_provisioning(uuid,uuid,text,text,public.app_role,uuid[],uuid)','EXECUTE'));
SELECT pg_temp.assert_true('finish closed',NOT has_function_privilege('service_role','public.b2b_finish_provisioning(uuid,uuid,uuid)','EXECUTE'));
GRANT EXECUTE ON FUNCTION public.b2b_claim_provisioning(uuid,uuid,text,text),public.b2b_claim_provisioning(uuid,uuid,text,text,public.app_role,uuid[],uuid),platform_private.b2b_claim_provisioning(uuid,uuid,text,text,public.app_role,uuid[],uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.b2b_finish_provisioning(uuid,uuid,uuid),public.b2b_prepare_provisioning_compensation(uuid,uuid,uuid),public.b2b_complete_provisioning_compensation(uuid,uuid,uuid) TO service_role;
CREATE FUNCTION pg_temp.denied(label text,statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 BEGIN EXECUTE statement; EXCEPTION WHEN SQLSTATE '42501' OR unique_violation OR SQLSTATE '22023' THEN RAISE NOTICE 'PASS %',label; RETURN; END; RAISE EXCEPTION 'FAIL %',label; END $$;
CREATE TEMP TABLE claims(label text,body jsonb); GRANT ALL ON claims TO authenticated,service_role;
INSERT INTO public.clientes(id,organization_id) VALUES('11111111-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('22222222-aaaa-4aaa-8aaa-aaaaaaaaaaaa','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('33333333-bbbb-4bbb-8bbb-bbbbbbbbbbbb','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
SELECT set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
SET LOCAL ROLE authenticated;
INSERT INTO claims VALUES('manager',public.b2b_claim_provisioning('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','manager@example.invalid','Manager'));
INSERT INTO claims VALUES('tech',public.b2b_claim_provisioning('22222222-2222-4222-8222-222222222222','66666666-6666-4666-8666-666666666666','tech@example.invalid','Tech','parceiro_b2b_tecnico',ARRAY[]::uuid[],NULL));
INSERT INTO claims VALUES('producer',public.b2b_claim_provisioning(NULL,'77777777-7777-4777-8777-777777777777','producer@example.invalid','Producer','cliente_produtor',ARRAY['11111111-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-aaaa-4aaa-8aaa-aaaaaaaaaaaa']::uuid[],'11111111-aaaa-4aaa-8aaa-aaaaaaaaaaaa'));
SELECT pg_temp.assert_true('retry does not reacquire',public.b2b_claim_provisioning('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','manager@example.invalid','Manager')->>'acquired'='false');
SELECT pg_temp.denied('foreign partner',$$SELECT public.b2b_claim_provisioning('33333333-3333-4333-8333-333333333333',gen_random_uuid(),'foreign@example.invalid','Foreign')$$);
SELECT pg_temp.denied('sibling cannot replace receipt',$$SELECT public.b2b_claim_provisioning('22222222-2222-4222-8222-222222222222','55555555-5555-4555-8555-555555555555','manager@example.invalid','Manager')$$);
SELECT pg_temp.denied('staff role rejected',$$SELECT public.b2b_claim_provisioning(NULL,gen_random_uuid(),'staff@example.invalid','Staff','administrador',ARRAY[]::uuid[],NULL)$$);
SELECT pg_temp.denied('foreign client',$$SELECT public.b2b_claim_provisioning(NULL,gen_random_uuid(),'foreignc@example.invalid','Foreign','cliente_produtor',ARRAY['33333333-bbbb-4bbb-8bbb-bbbbbbbbbbbb']::uuid[],'33333333-bbbb-4bbb-8bbb-bbbbbbbbbbbb')$$);
SELECT pg_temp.denied('empty producer',$$SELECT public.b2b_claim_provisioning(NULL,gen_random_uuid(),'empty@example.invalid','Empty','cliente_produtor',ARRAY[]::uuid[],NULL)$$);
SELECT pg_temp.denied('email no adoption',$$SELECT public.b2b_claim_provisioning('22222222-2222-4222-8222-222222222222',gen_random_uuid(),'manager@example.invalid','Manager')$$);
RESET ROLE;
INSERT INTO auth.users(id,email,raw_app_meta_data) SELECT (body->>'user_id')::uuid,label||'@example.invalid',jsonb_build_object('b2b_provisioning_receipt',body->>'claim_id') FROM claims;
SELECT set_config('request.jwt.claim.sub','',true);
SET LOCAL ROLE service_role;
SELECT pg_temp.assert_true('finish '||label,public.b2b_finish_provisioning((body->>'claim_id')::uuid,(body->>'fence')::uuid,(body->>'user_id')::uuid)->>'success'='true') FROM claims;
SELECT pg_temp.assert_true('replay '||label,public.b2b_finish_provisioning((body->>'claim_id')::uuid,(body->>'fence')::uuid,(body->>'user_id')::uuid)->>'replay'='true') FROM claims;
SELECT pg_temp.assert_true('completed never compensated '||label,public.b2b_prepare_provisioning_compensation((body->>'claim_id')::uuid,(body->>'fence')::uuid,(body->>'user_id')::uuid)='completed') FROM claims;
RESET ROLE;
SELECT pg_temp.assert_true('dedicated tech role',count(*)=1 AND min(role::text)='parceiro_b2b_tecnico') FROM public.user_roles WHERE user_id=(SELECT (body->>'user_id')::uuid FROM claims WHERE label='tech');
SELECT pg_temp.assert_true('sibling links exact',count(*)=1 AND min(partner_id::text)='22222222-2222-4222-8222-222222222222') FROM public.partner_users WHERE user_id=(SELECT (body->>'user_id')::uuid FROM claims WHERE label='tech');
SELECT pg_temp.assert_true('producer exact clients',count(*)=2 AND count(*) FILTER(WHERE principal)=1 AND bool_and(is_active)) FROM public.user_clientes WHERE user_id=(SELECT (body->>'user_id')::uuid FROM claims WHERE label='producer');
UPDATE public.user_clientes SET is_active=false WHERE user_id=(SELECT (body->>'user_id')::uuid FROM claims WHERE label='producer');
SET LOCAL ROLE service_role;
SELECT pg_temp.denied('revoked client replay denied',format('SELECT public.b2b_finish_provisioning(%L::uuid,%L::uuid,%L::uuid)',body->>'claim_id',body->>'fence',body->>'user_id')) FROM claims WHERE label='producer';
RESET ROLE;
UPDATE public.partner_accounts SET commercial_owner_organization_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb' WHERE id='22222222-2222-4222-8222-222222222222';
SET LOCAL ROLE service_role;
SELECT pg_temp.denied('changed partner denied',format('SELECT public.b2b_finish_provisioning(%L::uuid,%L::uuid,%L::uuid)',body->>'claim_id',body->>'fence',body->>'user_id')) FROM claims WHERE label='tech';
RESET ROLE;
UPDATE public.partner_accounts SET commercial_owner_organization_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' WHERE id='22222222-2222-4222-8222-222222222222';
UPDATE public.clientes SET status_cliente='inativo' WHERE id='22222222-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
SELECT set_config('request.jwt.claim.sub','44444444-4444-4444-8444-444444444444',true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.denied('inactive producer client',$$SELECT public.b2b_claim_provisioning(NULL,gen_random_uuid(),'inactive@example.invalid','Inactive','cliente_produtor',ARRAY['22222222-aaaa-4aaa-8aaa-aaaaaaaaaaaa']::uuid[],'22222222-aaaa-4aaa-8aaa-aaaaaaaaaaaa')$$);
INSERT INTO claims VALUES('pending',public.b2b_claim_provisioning('11111111-1111-4111-8111-111111111111','88888888-8888-4888-8888-888888888888','pending@example.invalid','Pending'));
RESET ROLE;
INSERT INTO auth.users(id,email,raw_app_meta_data) SELECT (body->>'user_id')::uuid,'pending@example.invalid',jsonb_build_object('b2b_provisioning_receipt',body->>'claim_id') FROM claims WHERE label='pending';
CREATE FUNCTION pg_temp.inject_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'isolated_failure' USING ERRCODE='42501'; END $$;
CREATE TRIGGER injected BEFORE INSERT ON platform_private.provisional_password_state FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_failure();
SELECT set_config('request.jwt.claim.sub','',true);
SET LOCAL ROLE service_role;
SELECT pg_temp.denied('last write failure',format('SELECT public.b2b_finish_provisioning(%L::uuid,%L::uuid,%L::uuid)',body->>'claim_id',body->>'fence',body->>'user_id')) FROM claims WHERE label='pending';
RESET ROLE;
SELECT pg_temp.assert_true('atomic rollback no role or tenant',p.organization_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p.user_id)) FROM public.profiles p WHERE email='pending@example.invalid';
DROP TRIGGER injected ON platform_private.provisional_password_state;
UPDATE public.profiles SET ativo=false WHERE user_id='44444444-4444-4444-8444-444444444444';
SET LOCAL ROLE service_role;
SELECT pg_temp.denied('actor revoked finish denied',format('SELECT public.b2b_finish_provisioning(%L::uuid,%L::uuid,%L::uuid)',body->>'claim_id',body->>'fence',body->>'user_id')) FROM claims WHERE label='pending';
SELECT pg_temp.assert_true('own receipt prepares compensation',public.b2b_prepare_provisioning_compensation((body->>'claim_id')::uuid,(body->>'fence')::uuid,(body->>'user_id')::uuid)='compensating') FROM claims WHERE label='pending';
SELECT pg_temp.denied('compensation not acknowledged while auth exists',format('SELECT public.b2b_complete_provisioning_compensation(%L::uuid,%L::uuid,%L::uuid)',body->>'claim_id',body->>'fence',body->>'user_id')) FROM claims WHERE label='pending';
RESET ROLE;
DELETE FROM auth.users WHERE id=(SELECT (body->>'user_id')::uuid FROM claims WHERE label='pending');
SET LOCAL ROLE service_role;
SELECT pg_temp.assert_true('compensation after own deletion',public.b2b_complete_provisioning_compensation((body->>'claim_id')::uuid,(body->>'fence')::uuid,(body->>'user_id')::uuid)) FROM claims WHERE label='pending';
RESET ROLE;
